import { randomBytes } from 'node:crypto';
import { open, rename, rm, stat } from 'node:fs/promises';
import { basename, dirname, join, resolve } from 'node:path';
import { UTF8_BOM, formatCsvRow } from './csv.js';
import { CsvWriter } from './csv-writer.js';
import { listColumns, quoteIdentifier } from './db.js';
import { CliError, dbError, describeCause, ioError, usageError } from './errors.js';

/**
 * 构造只导出指定列的查询语句。
 * @param {string} table
 * @param {readonly string[]} columns
 * @param {string | undefined} where
 * @returns {string}
 */
export function buildSelectSql(table, columns, where) {
  const columnList = columns.map(quoteIdentifier).join(', ');
  const condition = typeof where === 'string' ? where.trim() : '';
  return `SELECT ${columnList} FROM ${quoteIdentifier(table)}${condition ? ` WHERE ${condition}` : ''}`;
}

/**
 * 在写文件之前检查输出路径，提前给出中文错误。
 * @param {string} targetPath 已解析为绝对路径
 * @param {{ force: boolean }} options
 */
async function ensureOutputAvailable(targetPath, { force }) {
  const dir = dirname(targetPath);

  let dirStats;
  try {
    dirStats = await stat(dir);
  } catch {
    throw ioError(`输出目录不存在：${dir}。请先创建目录，或修改 --output 参数。`);
  }
  if (!dirStats.isDirectory()) {
    throw ioError(`输出路径的上级不是目录：${dir}。请检查 --output 参数。`);
  }

  let targetStats;
  try {
    targetStats = await stat(targetPath);
  } catch (error) {
    if (error.code === 'ENOENT') return;
    throw ioError(`无法检查输出文件：${targetPath}（底层错误：${describeCause(error)}）`, {
      cause: error,
    });
  }

  if (targetStats.isDirectory()) {
    throw ioError(`输出路径是一个目录：${targetPath}。请指定 CSV 文件路径。`);
  }
  if (!force) {
    throw ioError(`输出文件已存在：${targetPath}。如需覆盖，请加 --force。`);
  }
}

/**
 * 生成同目录下的临时文件路径，写完后再重命名，避免留下半截文件。
 * @param {string} targetPath
 */
function buildTempPath(targetPath) {
  const suffix = randomBytes(4).toString('hex');
  return join(dirname(targetPath), `.${basename(targetPath)}.tmp-${process.pid}-${suffix}`);
}

/**
 * 把临时文件重命名成目标文件；目标已存在时按 force 决定是否覆盖。
 * @param {string} tempPath
