 * @param {string} targetPath
 * @param {{ force: boolean }} options
 */
async function commitOutput(tempPath, targetPath, { force }) {
  if (force) {
    try {
      await rename(tempPath, targetPath);
      return;
    } catch (error) {
      if (!['EEXIST', 'EPERM', 'EACCES'].includes(error.code)) {
        throw ioError(`把临时文件重命名为输出文件失败：${targetPath}（底层错误：${describeCause(error)}）`, {
          cause: error,
        });
      }
      // Windows 等平台不允许直接覆盖，先删除再重命名。
      await rm(targetPath, { force: true });
      await rename(tempPath, targetPath);
      return;
    }
  }
  await rename(tempPath, targetPath);
}

/**
 * 把数据表导出为 CSV 文件。
 * @param {object} options
 * @param {import('node:sqlite').DatabaseSync} options.db 已打开的数据库连接
 * @param {string} options.table 表名
 * @param {string} options.outputPath 输出文件路径
 * @param {string} [options.where] 简单过滤条件（拼接到 WHERE 之后）
 * @param {readonly string[]} [options.exclude] 要排除的列
 * @param {string} [options.nullAs] NULL 值的输出文本
 * @param {boolean} [options.bom] 是否写入 UTF-8 BOM
 * @param {boolean} [options.force] 输出文件已存在时是否覆盖
 * @returns {Promise<{ rowCount: number, columns: string[], outputPath: string }>}
 */
export async function exportTable({
  db,
  table,
  outputPath,
  where,
  exclude = [],
  nullAs = '',
  bom = false,
  force = false,
}) {
  const allColumns = listColumns(db, table);

  const excluded = new Set(exclude);
  const unknownColumns = [...excluded].filter((name) => !allColumns.includes(name));
  if (unknownColumns.length > 0) {
    throw usageError(
      `要排除的列不存在：${unknownColumns.join('、')}。数据表 ${table} 的列为：${allColumns.join('、')}。`,
    );
  }

  const columns = allColumns.filter((name) => !excluded.has(name));
  if (columns.length === 0) {
    throw usageError(`排除后没有可导出的列：请检查 --exclude 参数。数据表 ${table} 的列为：${allColumns.join('、')}。`);
  }

  const targetPath = resolve(outputPath);
  await ensureOutputAvailable(targetPath, { force });

  const sql = buildSelectSql(table, columns, where);
  let statement;
  try {
    statement = db.prepare(sql);
  } catch (error) {
    throw dbError(
      `查询数据表 ${table} 失败，请检查 --where 条件（底层错误：${describeCause(error)}）`,
      { cause: error },
    );
  }

  const tempPath = buildTempPath(targetPath);
  let handle;
  try {
    handle = await open(tempPath, 'wx', 0o644);
  } catch (error) {
    throw ioError(`无法创建临时输出文件：${tempPath}（底层错误：${describeCause(error)}）`, {
      cause: error,
    });
  }

  let rowCount = 0;
  try {
    const writer = new CsvWriter(handle);
    if (bom) {
      await writer.writeRaw(UTF8_BOM);
    }
    await writer.writeLine(formatCsvRow(columns));

    const iterator = statement.iterate();
    while (true) {
      let next;
      try {
        next = iterator.next();
      } catch (error) {
        throw dbError(
          `读取数据表 ${table} 的记录失败（底层错误：${describeCause(error)}）`,
          { cause: error },
        );
      }
      if (next.done) break;

      const row = next.value;
      const values = columns.map((name) => row[name]);
      await writer.writeLine(formatCsvRow(values, nullAs));
      rowCount += 1;
    }

    await writer.close();
    await handle.close();
    handle = undefined;
    await commitOutput(tempPath, targetPath, { force });
  } catch (error) {
    if (handle) {
      try {
        await handle.close();
      } catch {
        // 关闭失败不覆盖原始错误。
      }
    }
    try {
      await rm(tempPath, { force: true });
    } catch {
      // 清理临时文件失败不覆盖原始错误。
    }
    if (error instanceof CliError) throw error;
    throw ioError(`写入 CSV 文件失败：${targetPath}（底层错误：${describeCause(error)}）`, {
      cause: error,
    });
  }

  return { rowCount, columns, outputPath: targetPath };
}

import { LINE_ENDING } from './csv.js';

const DEFAULT_FLUSH_THRESHOLD = 64 * 1024;

/**
 * 把数据写入文件句柄，确保写满整个缓冲区（处理部分写入）。
 * @param {import('node:fs/promises').FileHandle} handle
 * @param {Buffer} buffer
 */
async function writeFully(handle, buffer) {
  let offset = 0;
  while (offset < buffer.length) {
    const { bytesWritten } = await handle.write(buffer, offset, buffer.length - offset);
    if (bytesWritten === 0) {
      throw new Error('写入文件时没有写入任何字节');
    }
    offset += bytesWritten;
  }
}

/**
 * 带缓冲的 CSV 写入器：按行累积，达到阈值后一次写入文件，避免整表读入内存。
 */
export class CsvWriter {
  /** @type {import('node:fs/promises').FileHandle | undefined} */
  #handle;
  /** @type {string[]} */
  #chunks = [];
  #size = 0;
  #flushThreshold;
  #closed = false;

  /**
   * @param {import('node:fs/promises').FileHandle} handle
   * @param {{ flushThreshold?: number }} [options]
   */
  constructor(handle, { flushThreshold = DEFAULT_FLUSH_THRESHOLD } = {}) {
    this.#handle = handle;
    this.#flushThreshold = flushThreshold;
  }

  /**
   * 直接写入原始字节（例如 BOM），会先冲刷已缓冲的文本。
   * @param {Buffer} buffer
   */
  async writeRaw(buffer) {
    this.#assertOpen();
    await this.flush();
    await writeFully(this.#handle, buffer);
  }

  /**
   * 写入一行 CSV 内容，自动追加行分隔符。
   * @param {string} line
   */
  async writeLine(line) {
    this.#assertOpen();
    this.#chunks.push(line, LINE_ENDING);
    this.#size += Buffer.byteLength(line) + LINE_ENDING.length;
    if (this.#size >= this.#flushThreshold) {
      await this.flush();
    }
  }

  /** 把缓冲区内容写入文件。 */
  async flush() {
    this.#assertOpen();
    if (this.#chunks.length === 0) return;
    const text = this.#chunks.join('');
    this.#chunks = [];
    this.#size = 0;
    await writeFully(this.#handle, Buffer.from(text, 'utf8'));
  }

  /** 冲刷并结束写入（不关闭文件句柄）。 */
  async close() {
    if (this.#closed) return;
    await this.flush();
    this.#closed = true;
  }

  #assertOpen() {
    if (this.#closed || !this.#handle) {
      throw new Error('CSV 写入器已经关闭');
    }
  }
}
